#include <cstdio>
#include <memory_resource>
#include <utility>
#include <vector>

int main() {
  std::pmr::monotonic_buffer_resource r1, r2;
  std::pmr::vector<int> a({1, 2, 3}, &r1);
  std::pmr::vector<int> b(&r2);
  const int* old = a.data();
  b = std::move(a);
  std::printf("%d %d %zu\n", b.get_allocator().resource() == &r2,
              b.data() == old, b.size());
}

